def head_stats(L):
    out=[]
    for kind in ['q_proj','o_proj']:
        a=weights[f'X.layers.{L}.self_attn.{kind}.weight']; b=weights[f'Y.layers.{L}.self_attn.{kind}.weight']
        d=a-b
        for h in range(4):
            if kind=='q_proj': dd=d[256*h:256*h+256]; aa=a[256*h:256*h+256]
            else: dd=d[:,256*h:256*h+256]; aa=a[:,256*h:256*h+256]
            out.append(f"{kind[0]}{h}:{np.linalg.norm(dd)/np.linalg.norm(aa):.4f}/{(dd!=0).mean():.2f}")
    for kind in ['k_proj','v_proj']:
        a=weights[f'X.layers.{L}.self_attn.{kind}.weight']; b=weights[f'Y.layers.{L}.self_attn.{kind}.weight']
        out.append(f"{kind[0]}:{np.linalg.norm(a-b)/np.linalg.norm(a):.4f}/{(a!=b).mean():.2f}")
    return ' '.join(out)
