def groupcopy(ids_single, ids_space, M):
    allids=ids_single+ids_space
    EL=E[allids]
    S=(EL*np.sqrt(640))@M.T@(E[allids]*fn).T
    n=len(ids_single)
    S4=S[:n,:n]+S[n:,n:]+S[:n,n:]+S[n:,:n]
    return (torch.diag(S4).mean()-S4.mean()).item()
